mapper.update:
{CALL
    DECLARE
    v_sql varchar2(500);
    BEGIN
    v_sql :=
    'CREATE SEQUENCE ${tableName}_SEQ START WITH 1  MAXVALUE 99999999 MINVALUE 1 CYCLE CACHE 20 NOORDER';
    execute immediate v_sql;

    v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName}(MO_ACCEPTTIME)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName}(MO_SENDER)';
    execute immediate v_sql;

    v_sql := 'CREATE INDEX ${tableName}_IDX3 ON ${tableName}(MO_STATUS)';
    execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX4 ON ${tableName}(MO_SN)';
        execute immediate v_sql;
    END
}
